#include "PluginEditor.h"
namespace{const juce::Colour bg(0xff090a0d),panel(0xff12151c),grid(0xff292e39),white(0xfff2f3f7),muted(0xff858b9b),violet(0xffa58bff),cyan(0xff6bd9e8);}
CoolToneAudioProcessorEditor::CoolToneAudioProcessorEditor(CoolToneAudioProcessor&p):AudioProcessorEditor(&p),proc(p){
 setLookAndFeel(&lf);lf.setColour(juce::Slider::rotarySliderFillColourId,violet);lf.setColour(juce::Slider::rotarySliderOutlineColourId,grid);lf.setColour(juce::Slider::thumbColourId,white);lf.setColour(juce::Label::textColourId,muted);lf.setColour(juce::ComboBox::backgroundColourId,panel);lf.setColour(juce::ComboBox::textColourId,white);lf.setColour(juce::ComboBox::outlineColourId,grid);lf.setColour(juce::TextButton::buttonColourId,panel);lf.setColour(juce::TextButton::textColourOffId,white);
 key.addItemList({"C","C#","D","D#","E","F","F#","G","G#","A","A#","B"},1);scale.addItemList({"Major","Natural Minor","Harmonic Minor","Melodic Minor","Major Pentatonic","Minor Pentatonic","Blues","Jazz","Dorian","Phrygian","Lydian","Mixolydian","Chromatic","Custom"},1);
 preset.addItem("ORYMY SIGNATURE",1);preset.addItem("ROMANTIC BACHATA",2);preset.addItem("R&B EXPRESSIVE",3);preset.addItem("NATURAL VOCAL",4);preset.addItem("HARD TUNE",5);
 preset.onChange=[this]{int id=preset.getSelectedId();auto set=[this](const char*n,float v){if(auto*x=proc.state.getParameter(n))x->setValueNotifyingHost(x->convertTo0to1(v));};if(id==2){set("strength",.72f);set("retune",65);set("vibAmount",.68f);set("vibDepth",32);}else if(id==3){set("strength",.82f);set("retune",28);set("vibAmount",.52f);}else if(id==4){set("strength",.45f);set("retune",110);set("vibAmount",.3f);}else if(id==5){set("strength",1);set("retune",5);set("vibAmount",0);}else{set("strength",.85f);set("retune",35);set("vibAmount",.45f);}};
 auto cfg=[](juce::Slider&s){s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s.setTextBoxStyle(juce::Slider::TextBoxBelow,false,70,19);};for(auto*s:{&strength,&retune,&amount,&rate,&depth,&output})cfg(*s);
 add(strength,l1,"PITCH STRENGTH");add(retune,l2,"RETUNE SPEED");add(amount,l3,"VIBRATO AMOUNT");add(rate,l4,"VIBRATO RATE");add(depth,l5,"VIBRATO DEPTH");add(output,l6,"OUTPUT");
 addAndMakeVisible(key);addAndMakeVisible(scale);addAndMakeVisible(preset);addAndMakeVisible(magic);addAndMakeVisible(bypass);
 ka=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(proc.state,"key",key);sa=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(proc.state,"scale",scale);ma=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(proc.state,"magic",magic);ba=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(proc.state,"bypass",bypass);
 a1=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(proc.state,"strength",strength);a2=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(proc.state,"retune",retune);a3=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(proc.state,"vibAmount",amount);a4=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(proc.state,"vibRate",rate);a5=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(proc.state,"vibDepth",depth);a6=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(proc.state,"output",output);
 magic.setClickingTogglesState(true);magic.setColour(juce::TextButton::buttonOnColourId,juce::Colour(0xff493c73));bypass.setClickingTogglesState(true);setResizable(true,true);setResizeLimits(900,560,1600,1000);setSize(1180,720);startTimerHz(30);
}
CoolToneAudioProcessorEditor::~CoolToneAudioProcessorEditor(){setLookAndFeel(nullptr);}
void CoolToneAudioProcessorEditor::add(juce::Slider&s,juce::Label&l,const juce::String&t){addAndMakeVisible(s);l.setText(t,juce::dontSendNotification);l.setJustificationType(juce::Justification::centred);l.setFont(juce::Font(10,juce::Font::bold));addAndMakeVisible(l);}
void CoolToneAudioProcessorEditor::timerCallback(){repaint();}
void CoolToneAudioProcessorEditor::paint(juce::Graphics&g){
 g.fillAll(bg);g.setColour(panel);g.fillRoundedRectangle(16,14,getWidth()-32.0f,54,10);g.setColour(white);g.setFont(juce::Font(24,juce::Font::bold));g.drawText("COOLTONE",34,22,180,28,juce::Justification::left);g.setColour(violet);g.setFont(juce::Font(10,juce::Font::bold));g.drawText("BY ORYMY  /  YMY RECORDS",205,30,220,18,juce::Justification::left);
 g.setColour(panel);g.fillRoundedRectangle(22,126,getWidth()*.65f,getHeight()-166.0f,12);g.setColour(white);g.setFont(juce::Font(12,juce::Font::bold));g.drawText("PITCH MONITOR",38,136,220,20,juce::Justification::left);
 juce::Rectangle<float>r(36,166,getWidth()*.65f-30,getHeight()-220.0f);g.setColour(grid);for(int i=0;i<13;++i)g.drawHorizontalLine(static_cast<int>(r.getY()+r.getHeight()*i/12),r.getX(),r.getRight());for(int i=0;i<17;++i)g.drawVerticalLine(static_cast<int>(r.getX()+r.getWidth()*i/16),r.getY(),r.getBottom());
 juce::Path path;bool start=false;for(int i=255;i>=0;--i){float m=proc.history(i);if(m<0)continue;float x=r.getRight()-static_cast<float>(255-i)*r.getWidth()/255,y=r.getBottom()-juce::jlimit(0.0f,1.0f,(m-48)/36)*r.getHeight();if(!start){path.startNewSubPath(x,y);start=true;}else path.lineTo(x,y);}g.setColour(cyan);g.strokePath(path,juce::PathStrokeType(2.2f));
 g.setColour(panel);g.fillRoundedRectangle(getWidth()*.69f,126,getWidth()*.29f,getHeight()-166.0f,12);g.setColour(white);g.setFont(juce::Font(12,juce::Font::bold));g.drawText("INTERPRETATION",static_cast<int>(getWidth()*.69f+14),136,220,20,juce::Justification::left);
 g.setColour(muted);g.setFont(juce::Font(10));float p=proc.pitch();g.drawText(p>0?"LIVE PITCH  "+juce::String(p,1)+" MIDI":"LIVE PITCH  --",38,getHeight()-74,240,20,juce::Justification::left);
}
void CoolToneAudioProcessorEditor::resized(){int w=getWidth(),rx=static_cast<int>(w*.70f)+16,kw=(w-rx-22)/2,top=178,kh=132;preset.setBounds(440,24,190,34);key.setBounds(640,24,78,34);scale.setBounds(726,24,150,34);magic.setBounds(w-285,24,150,34);bypass.setBounds(w-124,24,90,34);
 auto pos=[&](juce::Slider&s,juce::Label&l,int c,int row){int x=rx+c*kw,y=top+row*kh;s.setBounds(x+8,y+10,kw-16,94);l.setBounds(x+4,y+102,kw-8,20);};pos(strength,l1,0,0);pos(retune,l2,1,0);pos(amount,l3,0,1);pos(rate,l4,1,1);pos(depth,l5,0,2);pos(output,l6,1,2);}
